style.css:
@-moz-document regexp("https?://.*") {
:root {
        --edge-bg: #202124;
        --edge-surface: #2d2f33;
        --edge-hover: #3c4043;
        --edge-text: #ffffff;
        --edge-secondary: #b8b8b8;
        --edge-accent: #0a84ff;
        --edge-border: #4b4b4b;
    }

    html,
    body {
        background: var(--edge-bg) !important;
        color: var(--edge-text) !important;
    }

    div,
    section,
    article,
    nav,
    aside,
    header,
    footer,
    main {
        background: var(--edge-surface) !important;
        color: var(--edge-text) !important;
    }

    a {
        color: var(--edge-accent) !important;
    }

    button,
    input,
    textarea,
    select {
        background: var(--edge-surface) !important;
        color: var(--edge-text) !important;
        border: 1px solid var(--edge-border) !important;
        border-radius: 8px !important;
    }

    button:hover {
        background: var(--edge-hover) !important;
    }

    img,
    video {
        border-radius: 10px;
    }

    * {
        scrollbar-color: var(--edge-hover) var(--edge-bg);
    }
}
